  init:function(){
    var raw=document.getElementById('knyraw');
    if(!raw)return;
    var txt=raw.value.trim();
    if(!txt)return;
    var d;
    try{d=JSON.parse(txt)}catch(e){return}

    // Name + alias
    KNYc.set('cn-name',d.name,'Unknown');
    if(d.alias&&d.alias.trim())
      KNYc.set('cn-alias','"'+d.alias+'"');

    // Age / gender
    var ag=[];
    if(d.age)ag.push(d.age);
    if(d.gender)ag.push(d.gender);
    if(ag.length)document.getElementById('cn-agegender').textContent=ag.join(' · ');

    // Faction badge
    var fb=document.getElementById('cn-faction');
    var faction=d.faction||'';
    fb.textContent=faction||'Unknown';
    if(faction==='Demon Slayer Corps')fb.className='ch-badge badge-slayer';
    else if(faction==='Former Slayer')fb.className='ch-badge badge-fslayer';
    else if(faction==='Demon')fb.className='ch-badge badge-demon';
    else fb.className='ch-badge badge-neutral';

    // Rank / tier
    var rankEl=document.getElementById('cn-rank');
    var isSlayer=(faction==='Demon Slayer Corps'||faction==='Former Slayer');
    var isDemon=(faction==='Demon');
    if(isSlayer&&d.rank){
      rankEl.textContent=d.rank;
      rankEl.style.display='inline-block';
    } else if(isDemon&&d.demon_tier){
      rankEl.textContent=d.demon_tier;
      rankEl.style.display='inline-block';
      rankEl.style.background='rgba(200,48,64,.1)';
      rankEl.style.borderColor='rgba(200,48,64,.3)';
      rankEl.style.color='#e05060';
    }

    // Stats
    var stats=d.stats||{};
    ['str','spd','stm','int','wil','sen'].forEach(function(k){KNYc.setBar(k,stats[k])});

    // Power
    if(isSlayer&&d.breathing_style&&d.breathing_style!=='None'){
      document.getElementById('pow-slayer').style.display='block';
      KNYc.set('cn-breath',d.breathing_style);
      if(d.breathing_forms)KNYc.set('cn-breath-forms',d.breathing_forms);
      if(d.nichirin_colour){
        var nc=document.getElementById('cn-nichirin');
        nc.textContent='Nichirin: '+d.nichirin_colour;
        nc.style.display='inline-block';
      }
    }
    if(isDemon&&d.blood_demon_art){
      document.getElementById('pow-demon').style.display='block';
      KNYc.set('cn-bda-name',d.blood_demon_art,'No art');
      if(d.blood_demon_art_desc)KNYc.set('cn-bda-desc',d.blood_demon_art_desc);
      if(d.blood_demon_art_weakness){
        KNYc.set('cn-bda-weak',d.blood_demon_art_weakness);
        document.getElementById('cn-bda-weak-wrap').style.display='block';
      }
    }

    // Skills
    var skills=d.skills||[];
    var sw=document.getElementById('cn-skills');
    if(skills.length){
      sw.innerHTML='';
      skills.forEach(function(sk){
        // find tag by matching name to known IDs
        var tag='uni';
        Object.keys(SKILL_TAGS).forEach(function(id){
          if(id.replace(/_/g,' ').toLowerCase()===sk.toLowerCase())tag=SKILL_TAGS[id];
        });
        var chip=document.createElement('span');
        chip.className='sk-chip sk-'+tag;
        chip.textContent=sk;
        sw.appendChild(chip);
      });
    }

    // Quote
    if(d.quote&&d.quote.trim()){
      document.getElementById('cn-quote').textContent='"'+d.quote+'"';
      document.getElementById('cn-quote-name').textContent=d.name||'';
      document.getElementById('cn-quote-wrap').style.display='block';
    }

    // Trio
    KNYc.set('cn-goal',d.goal,'—');
    KNYc.set('cn-fate',d.fate,'—');
    KNYc.set('cn-bond',d.bond,'—');

    // Lore sections
    KNYc.set('cn-appearance',d.appearance,'Not provided');
    KNYc.set('cn-personality',d.personality,'Not provided');
    KNYc.set('cn-background',d.background,'Not provided');
    KNYc.set('cn-secret',d.secret,'Not provided');
    KNYc.set('cn-extra',d.extra,'Not provided');
  }
};

document.addEventListener('DOMContentLoaded',KNYc.init);
if(document.readyState!=='loading')KNYc.init();
